package com.hms.service; import com.hms.dao.PatientDao; import com.hms.model.Patient; import java.sql.SQLException; import java.util.List; public class PatientService{private final PatientDao dao;public PatientService(PatientDao d){dao=d;}public List<Patient> findAll(String s)throws SQLException{return dao.findAll(s);}public Patient save(Patient p)throws SQLException{return dao.save(p);}public Patient update(Patient p)throws SQLException{return dao.update(p);}public void delete(int id)throws SQLException{dao.delete(id);}}
